sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var admissions = [];

    var gr = new GlideRecordSecure('x_2130921_caresy_0_admission');
    gr.orderByDesc('admission_date');
    gr.query();

    while (gr.next()) {
        admissions.push({
            sys_id: gr.getUniqueValue(),

            admission_number: gr.getValue('number'),

            patient_sys_id: gr.getValue('patient'),
            patient: gr.getDisplayValue('patient'),

            admission_date: gr.getValue('admission_date'),
            expected_discharge_date: gr.getValue('expected_discharge_date'),

            department_sys_id: gr.getValue('department'),
            department: gr.getDisplayValue('department'),

            ward_sys_id: gr.getValue('ward'),
            ward: gr.getDisplayValue('ward'),

            bed_sys_id: gr.getValue('bed'),
            bed: gr.getDisplayValue('bed'),

            admission_type: gr.getDisplayValue('admission_type'),
            admission_status: gr.getDisplayValue('admission_status'),

            reason_for_admission: gr.getValue('reason_for_admission'),
            admission_notes: gr.getValue('admission_notes'),

            discharge_date: gr.getValue('discharge_date'),

            active: gr.getValue('active') == '1'
        });
    }

    response.setStatus(200);
    response.setBody({
        success: true,
        count: admissions.length,
        admissions: admissions
    });

})(request, response);
